/* Newestan Biyamoozim: language and writing lessons transcribed from the lower-page OCR sections.
   Each lesson is kept separate by term and Newestan Dars; supplementary examples are labelled in the notes. */
(()=>{
 const R=(fa,en,ar,whenEn,whenAr,exampleFa,exampleEn,exampleAr)=>({fa,en,ar,whenEn,whenAr,exampleFa,exampleEn,exampleAr});
 const S=(fa,en,ar,whenEn,whenAr,exampleFa,exampleEn,exampleAr)=>({fa,en,ar,whenEn,whenAr,exampleFa,exampleEn,exampleAr});
 const L=(source,titleFa,titleEn,titleAr,overviewEn,overviewAr,sections)=>({source,titleFa,titleEn,titleAr,overviewEn,overviewAr,sections});
 const D={
  1:{
   1:L("N1-01 · pp5–6","شناسهٔ فعل، ضمیر و جمله‌های محترمانه","Verb agreement, pronouns and polite forms","مطابقة الفعل والضمائر وصيغ الاحترام",
    "This lesson connects personal pronouns and nouns to the correct verb form. It also teaches the common name pattern and the respectful use of a plural verb for one respected person.",
    "يربط هذا الدرس الضمائر والأسماء بصيغة الفعل المناسبة، ويشرح تركيب ذكر الاسم، واستعمال الفعل بصيغة الجمع احتراماً لشخص واحد.",
    [S("مطابقت اسم و ضمیر با فعل","Noun/pronoun–verb agreement","مطابقة الاسم أو الضمير بالفعل","A singular subject normally takes a singular verb; a plural subject takes a plural verb. In respectful speech, a singular person may take a plural verb.","يأتي الفعل مفرداً عادةً مع الفاعل المفرد، وجمعاً مع الفاعل الجمع. وفي أسلوب الاحترام قد يُستعمل الفعل الجمع مع شخص واحد.","آنها استاد هستند.","They are a teacher (respectful).","هي أستاذةٌ، بصيغة الاحترام."),
     S("الگوی اسم در آغاز جمله","The name pattern","تركيب الاسم في بداية الجملة","When a sentence begins with اسم من، اسم تو، اسم او and similar phrases, the textbook model uses است.","عند بدء الجملة بعبارات مثل «اسم من» و«اسم او»، يستعمل نموذج الكتاب الفعل «است».","اسم او سعید است.","His name is Saeed.","اسمه سعيد.",""),
     S("صیغهٔ محترمانه","Respectful plural","صيغة الجمع للاحترام","Use ایشان with a plural verb when speaking respectfully about one person.","يُستعمل «ایشان» مع الفعل الجمع عند الحديث باحترام عن شخص واحد.","ایشان استاد هستند.","He/She is a teacher (respectful).","هو/هي أستاذ بصيغة الاحترام.")]),
   2:L("N1-02 · pp5–8","حرف اضافه و عبارت‌های زمانی","Prepositions and time expressions","حروف الجر والتعابير الزمنية",
    "The lesson practises با with a noun, expressions meaning before and after, and هنگام/زمان followed by a noun. These expressions tell us the tool, companion or time of an action.",
    "يتدرّب الدرس على «با» مع الاسم، وتراكيب قبل وبعد، و«هنگام/زمان» مع الاسم. وتبيّن هذه التراكيب الأداة أو المصاحِب أو زمن الفعل.",
    [S("با + اسم","با + noun","با + اسم","Use با for an instrument or a companion: with a pen, with a friend.","تُستعمل «با» للدلالة على الأداة أو المصاحبة: بالقلم، مع الصديق.","من با خودکار آبی می‌نویسم.","I write with a blue pen.","أكتب بقلم أزرق."),
     S("پیش از / قبل از و پس از / بعد از","Before and after","قبل وبعد","Place these expressions before a noun or noun phrase to locate an action in time.","تأتي هذه التراكيب قبل الاسم أو العبارة الاسمية لتحديد زمن الفعل.","قبل از کلاس مطالعه می‌کنم؛ بعد از کلاس به کتابخانه می‌روم.","I study before class; after class I go to the library.","أدرس قبل الدرس، وبعده أذهب إلى المكتبة."),
     S("هنگام / زمان + اسم","During / at the time of","أثناء / وقت + اسم","هنگام and زمان introduce the time when an action happens.","تُدخل «هنگام» و«زمان» وقت وقوع الفعل.","هنگام درس با دقت گوش می‌کنم.","I listen carefully during the lesson.","أستمع بانتباه أثناء الدرس.")]),
   3:L("N1-03 · pp5–6","صفت و ترکیب وصفی","Adjectives and ezafe phrases","الصفة والتركيب الإضافي",
    "Persian adjectives usually follow the noun they describe and are connected by ezafe. The OCR notes two common spellings after a silent final ه: خانهٔ بزرگ and خانه‌ی بزرگ.",
    "تأتي الصفة الفارسية عادةً بعد الاسم، ويربط بينهما تركيب الإضافة. ويذكر النص صورتين شائعتين بعد الهاء غير المنطوقة: «خانهٔ بزرگ» و«خانه‌ی بزرگ».",
    [S("اسم + اضافه + صفت","Noun + ezafe + adjective","اسم + إضافة + صفة","Put the noun first and the adjective after it; the ezafe links them.","يأتي الاسم أولاً ثم الصفة، وتربط بينهما الإضافة.","خانهٔ بزرگ","a large house","بيت كبير"),
     S("املای اضافه پس از ه غیرملفوظ","Writing ezafe after silent ه","كتابة الإضافة بعد الهاء غير المنطوقة","The book accepts both خانهٔ بزرگ and خانه‌ی بزرگ. Keep one style consistent in an exam.","يقبل الكتاب الصورتين «خانهٔ بزرگ» و«خانه‌ی بزرگ». والأفضل الالتزام بصورة واحدة في الامتحان.","خانهٔ پدربزرگ","grandfather's house","بيت الجدّ")]),
   4:L("N1-04 · pp5–6","ضمیرها و جایگزینی اسم","Pronouns and replacing nouns","الضمائر واستبدال الاسم",
    "This lesson practises personal pronouns and using a pronoun instead of repeating a noun. It also combines pronouns with descriptive adjectives.",
    "يتدرّب هذا الدرس على الضمائر الشخصية واستعمال الضمير بدلاً من تكرار الاسم، وعلى الجمع بين الضمير والصفة.",
    [S("ضمیر شخصی","Personal pronouns","الضمائر الشخصية","من، تو، او، ما، شما and آنها identify the subject. Choose the verb form that agrees with the pronoun.","تحدّد الضمائر «من، تو، او، ما، شما، آنها» الفاعل؛ ويجب اختيار الفعل المطابق للضمير.","او مهربان است. آنها دانشجو هستند.","He is kind. They are students.","هو لطيف. هم طلاب."),
     S("ضمیر به جای اسم","Pronoun instead of a repeated noun","الضمير بدلاً من تكرار الاسم","After naming a person or thing, use a pronoun when the reference is clear; this makes the paragraph less repetitive.","بعد ذكر الشخص أو الشيء، استعمل الضمير إذا كان المرجع واضحاً لتجنّب التكرار.","زهرا دانشجو است. او فارسی می‌خواند.","Zahra is a student. She studies Persian.","زهراء طالبة. هي تدرس الفارسية."),S("ضمیر پیوسته در ترکیب اضافی","Attached pronouns in ezafe phrases","الضمائر المتصلة في الإضافة","In an ezafe phrase, a possessive pronoun can attach to the noun instead of appearing as a separate word: پدر من → پدرم، مادر تو → مادرت، برادر او → برادرش، خواهر ما → خواهرمان، مادر آنها → مادرشان.","في تركيب الإضافة يمكن أن يتصل ضمير الملكية بالاسم بدلاً من استعماله منفصلاً: أبي، أمك، أخوه، أختنا، أمّهم.","پدر من هر روز کتاب می‌خواند؛ پدرم هر روز کتاب می‌خواند.","My father reads every day; my father reads every day (with the attached pronoun).","يقرأ أبي كل يوم؛ ويُختصر التركيب بضمير متصل."),S("ضمیر پیوسته به صفت","Pronoun attached to an adjective","اتصال الضمير بالصفة","In a noun–adjective phrase, the attached pronoun may follow the adjective: برادر بزرگم، خواهر کوچکت، لباس سفیدم، پسر بزرگش.","في تركيب الاسم والصفة قد يتصل الضمير بالصفة: أخي الأكبر، أختك الصغرى، قميصي الأبيض، ابنه الأكبر.","برادر بزرگم به مسجد می‌رود.","My older brother goes to the mosque.","يذهب أخي الأكبر إلى المسجد.")]),
   5:L("N1-05 · pp5–8","جمع «ها»، عبارت‌های مقداری و زمان","Plural ها, quantity expressions and time","جمع «ها» وتعبيرات الكمية والزمن",
    "The lesson introduces ها as a common plural marker, expressions such as یکی از and بعضی از, and ways to state hours and time ranges.",
    "يقدّم الدرس اللاحقة «ها» علامةً شائعة للجمع، وتعبيرات مثل «یکی از» و«بعضی از»، وطرق ذكر الساعة والمدّة الزمنية.",
    [S("اسم + ها","Noun + ها","الاسم + ها","Attach ها to many nouns to form a plural. The spelling of ها remains the same in speech and writing in the examples.","تُضاف «ها» إلى كثير من الأسماء لتكوين الجمع، وتبقى كتابتها كما هي في أمثلة الدرس.","کتاب‌ها","books","كتب"),
     S("یکی از / بعضی از","One of / some of","واحد من / بعض من","یکی از selects one member from a group; بعضی از refers to some members. Follow the phrase with a suitable noun.","تختار «یکی از» فرداً واحداً من مجموعة، وتشير «بعضی از» إلى بعض أفرادها.","یکی از دوستانم در دانشگاه درس می‌خواند.","One of my friends studies at university.","أحد أصدقائي يدرس في الجامعة."),
     S("از ساعت ... تا ساعت ...","From ... until ...","من الساعة ... إلى الساعة ...","Use this pattern to state a time range.","يُستعمل هذا التركيب لتحديد المدّة بين ساعتين.","از ساعت چهار تا ساعت شش مطالعه می‌کنم.","I study from four to six.","أدرس من الساعة الرابعة إلى السادسة."),S("جمع با ـان","Plural with ـان","الجمع باللاحقة ـان","Persian uses ها with many nouns. The suffix ان is used mainly with animate nouns and some paired body parts. Examples in the source: درخت‌ها / درختان and دست‌ها / دستان. Do not assume every noun accepts both endings.","تستعمل الفارسية «ها» مع كثير من الأسماء، وتستعمل «ان» غالباً مع أسماء العاقل وبعض أعضاء الجسم المزدوجة. من أمثلة المصدر: الأشجار «درخت‌ها/درختان» والأيدي «دست‌ها/دستان». ولا تفترض أن كل اسم يقبل اللاحقتين.","گنجشک‌ها از روی درخت پریدند.","The sparrows flew off the tree.","طارَت العصافير عن الشجرة."),S("عبارت‌های کمیت + اسم جمع","Quantifier expressions + plural noun","تعبيرات الكمية مع الاسم الجمع","The source lists: یکی از، بعضی از، برخی از، تعدادی از، گروهی از، بسیاری از، مقداری از. Follow these expressions with a plural noun in the textbook pattern.","يذكر المصدر: واحد من، بعض من، بعض، عدد من، مجموعة من، كثير من، مقدار من. ويأتي بعدها اسم جمع في نمط الكتاب.","یکی از استادان دانشگاه به مکه می‌رود.","One of the university professors goes to Mecca.","يذهب أحد أساتذة الجامعة إلى مكة.")]),
   6:L("N1-06 · pp5–8","حروف اضافهٔ از، به، در و با","Prepositions از, به, در and با","حروف الجر «از، به، در، با»",
    "The lesson explains common functions of prepositions: از ... به ... for movement from one place to another, در for location, and با for a companion or instrument.",
    "يشرح الدرس وظائف شائعة لحروف الجر: «از ... به ...» للحركة من مكان إلى آخر، و«در» للمكان، و«با» للمصاحبة أو الأداة.",
    [S("از ... به ...","From ... to ...","من ... إلى ...","Use this pair to show a starting point and destination.","يُستعمل الزوج لتحديد نقطة الانطلاق والوجهة.","من از خانه به دانشگاه می‌روم.","I go from home to university.","أذهب من البيت إلى الجامعة."),
     S("در + مکان","در + place","در + مكان","Use در before the place where an action happens or something is located.","تأتي «در» قبل المكان الذي يقع فيه الفعل أو يوجد فيه الشيء.","من در کتابخانه مطالعه می‌کنم.","I study in the library.","أدرس في المكتبة."),
     S("با + ابزار یا همراه","With an instrument or companion","با + أداة أو مصاحِب","Use با for the means of doing something or the person accompanying you.","تُستعمل «با» للأداة أو للشخص المصاحِب.","با اتوبوس به قم می‌روم.","I go to Qom by bus.","أذهب إلى قم بالحافلة.")]),
   7:L("N1-07 · pp5–8","صفت ساده، برتر و برترین","Positive, comparative and superlative adjectives","الصفة العادية والتفضيل والأعلى",
    "The chapter distinguishes a basic adjective, a comparison with تر, and a superlative with ترین. It also uses یکی از before a superlative plus a plural noun.",
    "يميّز الدرس بين الصفة العادية، والمقارنة بإضافة «تر»، وصيغة الأعلى بإضافة «ترین». ويستعمل «یکی از» قبل صيغة الأعلى مع اسم جمع.",
    [S("صفت ساده","Positive adjective","الصفة العادية","Use the adjective to describe a noun without comparing it.","تُستعمل الصفة لوصف الاسم من دون مقارنة.","کفش‌های زیبا","beautiful shoes","أحذية جميلة"),
     S("صفت + تر","Comparative: adjective + تر","التفضيل: الصفة + تر","Add تر to compare two people or things; often use از to introduce the comparison.","تُضاف «تر» للمقارنة بين شيئين، وغالباً تأتي «از» قبل الطرف الثاني.","این مغازه بزرگ‌تر از آن مغازه است.","This shop is bigger than that shop.","هذا المتجر أكبر من ذلك المتجر."),
     S("صفت + ترین","Superlative: adjective + ترین","صيغة الأعلى: الصفة + ترین","Use ترین for the highest degree in a group. The textbook also uses یکی از + superlative + plural noun.","تُستعمل «ترین» للدلالة على أعلى درجة ضمن مجموعة، ويستعمل الكتاب «یکی از» قبلها مع اسم جمع.","این یکی از زیباترین باغ‌های شهر است.","This is one of the most beautiful gardens in the city.","هذه واحدة من أجمل حدائق المدينة.")]),
   8:L("N1-08 · pp5–6","نهاد، مفعول و نشانهٔ «را»","Subject, object and the marker را","الفاعل والمفعول وعلامة «را»",
    "The lesson teaches how to identify the subject by asking چه کسی؟ or چه چیزی؟, and the object by asking چه کسی را؟ or چه چیزی را؟ The object marker را follows the object.",
    "يعلّم الدرس تحديد الفاعل بسؤال «چه کسی؟» أو «چه چیزی؟»، وتحديد المفعول بسؤال «چه کسی را؟» أو «چه چیزی را؟». وتأتي علامة المفعول «را» بعده.",
    [S("فاعل + مفعول + را + فعل","Subject + object + را + verb","فاعل + مفعول + را + فعل","The subject performs the action; the object receives it. In the textbook pattern, the verb comes at the end.","الفاعل يقوم بالفعل، والمفعول يقع عليه الفعل. وفي نمط الكتاب يأتي الفعل في نهاية الجملة.","زهرا سبزی‌ها را می‌شوید.","Zahra washes the vegetables.","زهراء تغسل الخضروات."),
     S("مفعول + را + با / در","Object + را + with / in","المفعول + را + با / در","Add با for the tool and در for the place where the action occurs.","أضف «با» للأداة و«در» للمكان الذي يقع فيه الفعل.","خواهرم گوشت را با چاقو خرد می‌کند.","My sister chops the meat with a knife.","تقطّع أختي اللحم بالسكين.")]),
   9:L("N1-09 · pp4–5","باید و شاید: الزام و احتمال","باید and شاید: obligation and possibility","«باید» و«شاید»: الوجوب والاحتمال",
    "The New Year text uses باید for an expected or necessary action and شاید for a possible action. These words commonly precede a present subjunctive verb form.",
    "يستعمل نصّ عيد النوروز «باید» للفعل المطلوب أو اللازم، و«شاید» للفعل المحتمل. وتأتي هاتان الكلمتان غالباً قبل الفعل المضارع الالتزامي.",
    [S("باید + فعل التزامی","باید + subjunctive","باید + المضارع الالتزامي","Use باید to express necessity, duty or a plan that must be carried out.","تُستعمل «باید» للتعبير عن الوجوب أو الواجب أو الخطة اللازمة.","باید به دیدار پدربزرگم بروم.","I must visit my grandfather.","يجب أن أزور جدّي."),
     S("شاید + فعل التزامی","شاید + subjunctive","شاید + المضارع الالتزامي","Use شاید to express possibility rather than certainty.","تُستعمل «شاید» للتعبير عن الاحتمال لا اليقين.","شاید فردا با ماشین سفر کنیم.","Perhaps we will travel by car tomorrow.","ربما نسافر بالسيارة غداً.")]),
   10:L("N1-10 · pp5–8","قید زمان، مکان و کمیت","Adverbs of time, place and quantity","ظروف الزمان والمكان والكمية",
    "The lesson groups adverbs by the question they answer: when, where and how much/how often. They add detail to the sentence and can appear in different positions.",
    "يصنّف الدرس الظروف بحسب السؤال الذي تجيب عنه: متى، وأين، وكم/إلى أي مدى. وهي تضيف تفصيلاً إلى الجملة ويمكن أن تأتي في مواضع مختلفة.",
    [S("قید زمان","Adverb of time","ظرف الزمان","Answers when or how often: همیشه، هر روز، گاهی، بیشتر وقت‌ها.","يجيب عن سؤال «متى؟» أو «كم مرة؟» مثل: دائماً، كل يوم، أحياناً.","من هر روز به دانشگاه می‌روم.","I go to university every day.","أذهب إلى الجامعة كل يوم."),
     S("قید مکان","Adverb of place","ظرف المكان","Answers where: در خانه، به دانشگاه، همه‌جا.","يجيب عن سؤال «أين؟» مثل: في البيت، إلى الجامعة، في كل مكان.","دوستانم در کتابخانه درس می‌خوانند.","My friends study in the library.","أصدقائي يدرسون في المكتبة."),
     S("قید کمیت","Adverb of quantity","ظرف الكمية","Shows degree or amount: بیشتر، زیاد، بسیار، کم، کمتر.","يدلّ على المقدار أو الدرجة: أكثر، كثيراً، قليلاً.","امسال در ایران خیلی زیاد باران بارید.","It rained a great deal in Iran this year.","هطلت أمطار كثيرة جداً في إيران هذا العام.")])
  },
  2:{
   1:L("N2-01 · pp5–7","زبان گفتاری و نوشتاری و نامه","Spoken and written Persian; letters","الفارسية المحكية والمكتوبة والرسائل",
    "The lesson compares spoken and written forms of verbs, nouns, adjectives and adverbs. Formal writing should use standard written forms and a register suited to the recipient.",
    "يقارن الدرس بين الصيغ المحكية والمكتوبة للأفعال والأسماء والصفات والظروف. وينبغي أن تستعمل الكتابة الرسمية الصيغ المعيارية والأسلوب المناسب للمخاطَب.",
    [S("گفتاری در برابر نوشتاری","Spoken vs written forms","المحكي مقابل المكتوب","Use standard written forms in essays and formal letters; colloquial spellings belong mainly in dialogue or direct quotation.","استعمل الصيغ المكتوبة المعيارية في المقالات والرسائل الرسمية، واترك الصيغ المحكية للحوار أو الاقتباس المباشر.","می‌خواهم به دانشگاه بروم. / می‌خوام برم دانشگاه.","I want to go to university. (written / spoken)","أريد الذهاب إلى الجامعة. (صيغة مكتوبة / محكية)"),
     S("لحن متناسب با مخاطب","Register for the reader","الأسلوب المناسب للمخاطَب","Choose the greeting, pronoun, request and closing according to whether the reader is a professor, office or friend.","اختر التحية والضمير والطلب والخاتمة بحسب كون المخاطَب أستاذاً أو مكتباً أو صديقاً.","استاد گرامی، با سلام و احترام...","Dear Professor, greetings and respect...","الأستاذ الكريم، تحية طيبة وبعد..."),S("تبدیل فعل گفتاری به نوشتاری","Converting spoken verbs to written forms","تحويل الأفعال المحكية إلى المكتوبة","The source contrasts forms such as می‌خوانم / می‌خونم and می‌روم / می‌رم. In essays and formal emails, use the standard written form; keep colloquial forms for dialogue or quoted speech.","يقارن المصدر بين صيغ مثل «می‌خوانم/می‌خونم» و«می‌روم/می‌رم». استعمل الصيغة المكتوبة المعيارية في المقالات والرسائل الرسمية، واترك المحكية للحوار أو الاقتباس.","امروز در کلاس چه می‌خوانی؟","What are you studying in class today?","ماذا تدرس اليوم في الصف؟"),S("تغییر اسم، ضمیر، جمع و حرف اضافه در گفتار","Colloquial changes to nouns, pronouns, plurals and prepositions","تغيّرات الأسماء والضمائر والجمع وحروف الجر في المحكية","Examples from the OCR: نان → نون، صبحانه → صبحونه، آن → اون، کتاب‌ها را → کتابا رو، اگر → اگه، یک → یه. Some pronoun–preposition forms also contract: به من → بهم، با او → باهاش. Some prepositions may be omitted and word order may change in speech.","من أمثلة OCR: نان تصبح نون، وصبحانه تصبح صبحونه، وآن تصبح اون، والكتبَ را تصبح کتابا رو، وإذا تصبح اگه، وواحد تصبح یه. وتختصر بعض تراكيب الضمير وحرف الجر مثل «به من» إلى «بهم»، وقد يُحذف حرف الجر أو يتغير ترتيب الكلمات في الكلام.","من دیروز کتاب را به دوستم دادم. / من دیروز کتابا رو به دوستم دادم.","I gave the book to my friend yesterday (written / spoken).","أعطيت الكتاب لصديقي أمس (مكتوب / محكي)."),S("ایمیل رسمی: عنوان تا ویرایش","Formal email: subject through proofreading","البريد الرسمي: من العنوان إلى المراجعة","The source checklist: choose a clear subject; begin with a respectful greeting; address the teacher by title and surname; write in formal standard Persian; keep the message concise (one paragraph unless longer); use a readable font and black text; close with thanks or a prayer phrase; sign with full name; reread and correct before sending.","قائمة المصدر: اختر عنواناً واضحاً؛ وابدأ بتحية محترمة؛ وخاطب الأستاذ بلقبه واسم عائلته؛ واكتب بالفارسية الرسمية المعيارية؛ واجعل الرسالة موجزة (فقرة واحدة ما لم تطل)؛ واستعمل خطاً واضحاً ولوناً أسود؛ واختم بالشكر أو الدعاء؛ واكتب الاسم الكامل؛ ثم راجع الرسالة وصحّحها قبل الإرسال.","استاد گرامی، با سلام و احترام؛ خواهشمندم فایل درس را برای من بفرستید. با سپاس، علی احمدی.","Dear Professor, greetings and respect. Please send me the lesson file. Thank you, Ali Ahmadi.","الأستاذ الكريم، تحية طيبة. أرجو إرسال ملف الدرس إليّ. مع الشكر، علي أحمدي.")]),
   2:L("N2-02 · pp5–6","انواع جمله و ترتیب اجزای جمله","Sentence types and word order","أنواع الجمل وترتيب أجزائها",
    "The chapter teaches the parts of a sentence and the usual Persian order: subject + verb, or subject + object + verb. It also asks learners to build a text from an opening, middle and ending.",
    "يعلّم الفصل مكوّنات الجملة والترتيب الفارسي المعتاد: الفاعل ثم الفعل، أو الفاعل ثم المفعول ثم الفعل. كما يطلب بناء النص من مقدمة ووسط وخاتمة.",
    [S("نهاد + فعل","Subject + verb","فاعل + فعل","Use this basic pattern when there is no expressed object.","استعمل هذا النمط الأساسي عندما لا يوجد مفعول ظاهر.","تیم برزیل برنده شد.","The Brazil team won.","فاز فريق البرازيل."),
     S("نهاد + مفعول + فعل","Subject + object + verb","فاعل + مفعول + فعل","Place the object before the verb in the common written pattern.","ضع المفعول قبل الفعل في النمط الكتابي الشائع.","تیم برزیل تیم هلند را برد.","The Brazil team defeated the Netherlands team.","هزم فريق البرازيل فريق هولندا."),
     S("مقدمه، جمله‌های میانی، پایان","Opening, middle and ending","المقدمة والوسط والخاتمة","Start by introducing the topic, develop it with supporting information, and finish with a concluding point.","ابدأ بتقديم الموضوع، ثم طوّره بالمعلومات الداعمة، واختم بفكرة ختامية.","در آغاز موضوع را معرفی کنید؛ در پایان نکتهٔ اصلی را جمع‌بندی کنید.","Introduce the topic first; summarise the main point at the end.","قدّم الموضوع أولاً، ثم لخّص الفكرة الأساسية في النهاية."),S("چهار نوع جمله از نظر پیام","Four sentence types by communicative purpose","أنواع الجمل الأربعة بحسب الرسالة","The OCR lists خبری (statement), پرسشی (question), امری (command/request) and عاطفی (exclamation/emotion). Choose punctuation and verb form according to the sentence's purpose.","يسرد OCR الجملة الخبرية والاستفهامية والأمرية والتعجبية/العاطفية. اختر علامة الترقيم وصيغة الفعل بحسب غرض الجملة.","چرا بازیکنان تیم ملی به عراق می‌روند؟","Why are the national team players going to Iraq?","لماذا يذهب لاعبو المنتخب الوطني إلى العراق؟"),S("واژه‌های پرسشی","Question words","أدوات الاستفهام","The source lists: چه کسی؟ for a person; چه / چه چیزی؟ for a thing; کجا؟ for place; کدام؟ for selection; چه زمانی؟ / چه وقتی؟ for time; چرا؟ / به چه علت؟ / به چه دلیل؟ for reason. Use the question word that matches the information you need.","يسرد المصدر: من؟ للشخص؛ ماذا؟ للشيء؛ أين؟ للمكان؛ أيّ؟ للاختيار؛ متى؟ للزمن؛ لماذا؟ ولأي سبب؟ للتعليل. استعمل أداة الاستفهام المناسبة للمعلومة المطلوبة.","چه زمانی باید فوتبال بازی کنیم؟","When should we play football?","متى ينبغي أن نلعب كرة القدم؟")]),
   3:L("N2-03 · pp5–6","فعل امر مفرد و جمع؛ جمله‌های امری و عاطفی","Singular/plural imperative; commands and exclamations","الأمر للمفرد والجمع والجمل التعجبية",
    "The lesson distinguishes the command addressed to one person from the command addressed to several people or a respected listener. It also introduces exclamatory sentences.",
    "يميّز الدرس بين الأمر الموجّه إلى شخص واحد والأمر الموجّه إلى جماعة أو مخاطَب بصيغة الاحترام، كما يعرّف الجمل التعجبية.",
    [S("امر مفرد","Singular imperative","الأمر للمفرد","Address one person informally: برو، بنویس، باز کن.","يُوجَّه إلى شخص واحد بصيغة غير رسمية: اذهب، اكتب، افتح.","کتابت را باز کن.","Open your book.","افتح كتابك."),
     S("امر جمع / محترمانه","Plural or respectful imperative","الأمر للجمع أو الاحترام","Address more than one person or one person respectfully: بروید، بنویسید، باز کنید.","يُوجَّه إلى جماعة أو إلى شخص باحترام: اذهبوا، اكتبوا، افتحوا.","لطفاً کتابتان را باز کنید.","Please open your books.","من فضلكم افتحوا كتبكم."),
     S("جملهٔ عاطفی","Exclamatory sentence","الجملة التعجبية","Expresses emotion such as surprise, regret, happiness, wish or anger.","تعبّر عن شعور مثل التعجب أو الأسف أو الفرح أو التمني أو الغضب.","چه هوای خوبی! کاش حالم بهتر می‌شد!","What lovely weather! If only I felt better!","يا له من طقس جميل! ليتني أشعر بتحسن!"),S("گزارش شرح حال بیماری","A report of an illness history","تقرير عن الحالة المرضية","For the chapter's real-life illness report, arrange events in order: the person's condition before illness, first symptoms, who was contacted, the medical visit, diagnosis and treatment, return home and recovery. Use time links such as وقتی، سپس، بعد از آن and در پایان; keep the report factual and in a consistent past tense.","في تقرير المرض رتّب الوقائع: حالة الشخص قبل المرض، والأعراض الأولى، ومن تم الاتصال به، وزيارة الطبيب، والتشخيص والعلاج، والعودة إلى البيت والتعافي. استعمل روابط زمنية مثل عندما، ثم، بعد ذلك، وفي النهاية، وحافظ على الأسلوب الواقعي وزمن الماضي.","وقتی به خانه رسیدم، مادرم منتظر بود؛ سپس داروهایم را خوردم و استراحت کردم.","When I got home, my mother was waiting; then I took my medicine and rested.","عندما وصلت إلى البيت كانت أمي تنتظر؛ ثم تناولت دوائي واستَرحت.")]),
   4:L("N2-04 · pp5–6","فعل‌های خاص با حرف اضافه","Verbs with fixed prepositions","الأفعال مع حروف الجر الملازمة",
    "Some Persian verbs commonly occur with a particular preposition. Learn the verb and preposition together as one useful pattern rather than translating each word separately.",
    "تأتي بعض الأفعال الفارسية عادةً مع حرف جرّ معيّن. تعلّم الفعل وحرف الجر معاً بوصفهما تركيباً واحداً بدلاً من ترجمة كل كلمة منفردة.",
    [S("از + متمم + فعل","از + complement + verb","از + متمم + فعل","Examples from the lesson include استفاده کردن، پرسیدن، ترسیدن، تشکر کردن and پیاده شدن with از.","من أمثلة الدرس: استعمال، سؤال، خوف، شكر، ونزول من وسيلة نقل مع «از».","من از خودکار استفاده می‌کنم.","I use a pen.","أستعمل قلماً."),
     S("به + متمم + فعل","به + complement + verb","به + متمم + فعل","Examples include به کسی دادن، به کسی کمک کردن، به کسی زنگ زدن، به کسی گفتن and به چیزی علاقه داشتن.","من الأمثلة: إعطاء شخص، مساعدة شخص، الاتصال به، إخباره، والاهتمام بشيء مع «به».","دخترم به آن پیرزن کمک کرد.","My daughter helped that elderly woman.","ساعدت ابنتي تلك المرأة المسنّة."),
     S("با / در + متمم + فعل","با / در + complement + verb","با / در + متمم + فعل","The chapter also gives patterns such as با کسی بازی کردن, با کسی ازدواج کردن, در چیزی ماندن and در چیزی غرق شدن.","يعرض الفصل أيضاً تراكيب مثل اللعب مع شخص، والزواج من شخص، والبقاء في مكان، والغرق في شيء.","بچه‌ها با توپ بازی می‌کنند.","The children play with a ball.","يلعب الأطفال بالكرة.")]),
   5:L("N2-05 · pp5–7","حروف ربط ساده و مرکب","Simple and compound conjunctions","حروف العطف البسيطة والمركّبة",
    "This is the chapter's central linking-words lesson. Simple conjunctions are one word; compound conjunctions contain more than one word. They connect clauses and show addition, contrast, choice, reason or time.",
    "هذا هو درس أدوات الربط الأساسي في الفصل. يتكوّن الرابط البسيط من كلمة واحدة، أما الرابط المركّب فيتكوّن من أكثر من كلمة. وتربط هذه الأدوات الجمل وتدلّ على الإضافة أو التضاد أو الاختيار أو السبب أو الزمن.",
    [S("حروف ربط ساده","Simple conjunctions","روابط بسيطة","The OCR examples include و، اما، ولی، هم، نیز، یا، چون، تا and که. Use each according to its relation.","تتضمن أمثلة النص: و، اما، ولی، هم، نیز، یا، چون، تا، که. اختر الأداة بحسب العلاقة بين الجمل.","علی آمد؛ اما رضا رفت.","Ali came, but Reza left.","جاء علي، لكن رضا ذهب."),
     S("حروف ربط مرکب","Compound conjunctions","روابط مركّبة","The OCR examples include به خاطر اینکه، به دلیل اینکه، همین که، هنگامی که and با این حال.","تتضمن أمثلة النص: بسبب أن، لأنّ، بمجرد أن، عندما، ومع ذلك.","من دیروز مدرسه نرفتم؛ به خاطر اینکه مریض بودم.","I did not go to school yesterday because I was ill.","لم أذهب إلى المدرسة أمس لأنني كنت مريضاً."),
     S("انتخاب رابط بر اساس معنا","Choose by meaning","اختيار الرابط بحسب المعنى","Use و for addition, اما/ولی for contrast, یا for alternatives, چون/به خاطر اینکه for reason, تا for purpose, and هنگامی که for time.","استعمل «و» للإضافة، و«اما/ولی» للتضاد، و«یا» للاختيار، و«چون/به خاطر اینکه» للسبب، و«تا» للغرض، و«هنگامی که» للزمن.","همین که خورشید طلوع کرد، ما به مسافرت رفتیم.","As soon as the sun rose, we went on the trip.","ما إن أشرقت الشمس حتى انطلقنا في الرحلة.")]),
   6:L("N2-06 · pp5–7","زمان‌های گذشته و قیدهای آن","Past tenses and their adverbs","أزمنة الماضي وظروفها",
    "The lesson contrasts simple past, past continuous and present perfect, with time expressions that help the reader recognise each tense. It also teaches memoir writing: real events, clear sequence, suitable opening and ending, concise wording and standard written language.",
    "يقارن الدرس بين الماضي البسيط والماضي المستمر والماضي النقلي، مع ظروف زمنية تساعد القارئ على تمييز كل زمن. كما يعلّم كتابة الذكريات: أحداثاً حقيقية، وتسلسلاً واضحاً، وبداية ونهاية مناسبتين، وعبارة موجزة ولغة مكتوبة معيارية.",
    [S("گذشتهٔ ساده: بن ماضی + شناسه","Simple past","الماضي البسيط","Use for a completed event in the past. Common clues: دیروز، دیشب، هفتهٔ قبل، پارسال.","يُستعمل لحدث اكتمل في الماضي. من علاماته: أمس، الليلة الماضية، الأسبوع الماضي، العام الماضي.","من دیشب به فرودگاه رفتم.","I went to the airport last night.","ذهبت إلى المطار ليلة أمس."),
     S("گذشتهٔ استمراری: می + گذشتهٔ ساده","Past continuous / habitual past","الماضي المستمر أو المعتاد","Use for an action repeated or continuing in the past. Common clues: هر روز، هر شب، هر هفته، هر سال.","يُستعمل لعمل كان متكرراً أو مستمراً في الماضي. من علاماته: كل يوم، كل ليلة، كل أسبوع، كل سنة.","او هر روز به دانشگاه می‌رفت.","He used to go to university every day.","كان يذهب إلى الجامعة كل يوم."),
     S("گذشتهٔ نقلی: صفت مفعولی + شناسه","Present perfect","الماضي النقلي","Use for a recent past event, or a past action whose result continues now. Clues include هنوز and تا حالا.","يُستعمل لحدث ماضٍ قريب أو لعمل ماضٍ ما زالت نتيجته مستمرة. من علاماته: حتى الآن، وما زال.","او هنوز به دانشگاه نرفته است.","He has not gone to university yet.","لم يذهب إلى الجامعة حتى الآن."),
     S("خاطره‌نویسی","Memoir writing","كتابة الذكريات","Write a real event, not an invented story; establish when it happened, arrange events in order, and use a clear beginning and ending.","اكتب حدثاً حقيقياً لا قصة مختلقة، وحدّد زمنه، ورتّب الوقائع، واجعل للنص بداية ونهاية واضحتين.","آن روز با اصرار از پدرم اجازه خواستم.","That day I insisted and asked my father for permission.","في ذلك اليوم ألححت على أبي وطلبت إذنه.")]),
   7:L("N2-07 · pp5–7","عبارت‌های قیدی برای آغاز، گذر زمان و نتیجه","Adverbial expressions for beginning, elapsed time and conclusion","التعابير الظرفية للبداية ومرور الزمن والنتيجة",
    "For memoirs, the chapter groups adverbial expressions into three functions: marking the beginning of an event, showing time passing, and drawing the story to a conclusion. It also explains where an adverb can appear in a sentence.",
    "يجمع الفصل تعابير الظروف في الذكريات ضمن ثلاث وظائف: تحديد بداية الحدث، وبيان مرور الزمن، والوصول إلى النتيجة. كما يشرح موضع الظرف في الجملة.",
    [S("آغاز رویداد","Beginning an event","بداية الحدث","The OCR gives expressions such as اولین روزی که and روز اولی که.","من أمثلة النص: أول يوم، واليوم الأول الذي...","اولین روزی که رانندگی کردم، تصادف کردم.","The first day I drove, I had an accident.","في أول يوم قدت فيه السيارة، تعرّضت لحادث."),
     S("گذر زمان","Time passing","مرور الزمن","Use بعد از پنج روز، بعد از یک ساعت and similar expressions to show elapsed time.","استعمل «بعد خمسة أيام» و«بعد ساعة» ونحوها لبيان الزمن المنقضي.","بعد از پنج روز به خانه برگشتم.","After five days, I returned home.","عدت إلى البيت بعد خمسة أيام."),
     S("نتیجه و پایان","Outcome and conclusion","النتيجة والخاتمة","The OCR lists سرانجام، بالاخره and در پایان for the concluding stage of a sequence.","يذكر النص «سرانجام» و«بالاخره» و«در پایان» لمرحلة الخاتمة.","سرانجام از بیمارستان مرخص شدم.","Eventually, I was discharged from hospital.","أُخرجت من المستشفى في نهاية المطاف."),
     S("جایگاه قید","Adverb position","موضع الظرف","An adverb may occur at the beginning, middle or end. In formal written Persian the verb normally remains last; keep the adverb close to the word it modifies.","قد يأتي الظرف في أول الجملة أو وسطها أو آخرها. وفي الفارسية المكتوبة الرسمية يبقى الفعل عادةً في النهاية؛ فقرّب الظرف من الكلمة التي يصفها.","خوشبختانه این مسافرت تمام شد.","Fortunately, this trip ended.","لحسن الحظ انتهت هذه الرحلة.")]),
   8:L("N2-08 · pp4–6","انواع قید در زبان فارسی","Types of Persian adverbs","أنواع الظروف في الفارسية",
    "The chapter lists several adverb types. Identify the question each answers, then use the adverb to add a precise detail without changing the core sentence meaning.",
    "يسرد الفصل أنواعاً متعددة من الظروف. حدّد السؤال الذي يجيب عنه كل ظرف، ثم استعمله لإضافة تفصيل دقيق من دون تغيير المعنى الأساسي للجملة.",
    [S("زمان، مکان، کیفیت، کمیت","Time, place, quality and quantity","الزمان والمكان والكيفية والكمية","Examples: دیروز (when), در آشپزخانه (where), خوب (how), کمی (how much).","أمثلة: أمس (متى)، في المطبخ (أين)، جيداً (كيف)، قليلاً (كم).","زهرا دیروز در آشپزخانه خوب غذا پخت.","Zahra cooked well in the kitchen yesterday.","طبخت زهراء الطعام جيداً في المطبخ أمس."),
     S("حالت، ترتیب، آرزو، تعجب","Manner, order, wish and surprise","الحال والترتيب والتمني والتعجب","The OCR also lists adverbs of manner/state, order, wish and surprise.","يذكر النص أيضاً ظروف الحال والترتيب والتمني والتعجب.","ابتدا وسایل را آماده کنید؛ سپس غذا را بپزید.","First prepare the tools; then cook the food.","جهّز الأدوات أولاً، ثم اطبخ الطعام."),
     S("شک، استثنا و علت","Doubt, exception and cause","الشك والاستثناء والسبب","Examples include شاید / ممکن است for doubt, جز / به‌جز for exception, and به این دلیل / بدین جهت for cause.","من أمثلة النص: ربما/من الممكن للشك، إلا/باستثناء للاستثناء، ولهذا السبب/لذلك للتعليل.","به این دلیل غذا را کمتر نمک زدم که سالم‌تر باشد.","For this reason I used less salt so it would be healthier.","لهذا السبب قلّلت الملح في الطعام ليكون أكثر صحة.")]),
   9:L("N2-09 · pp5–7","اعداد اصلی و ترتیبی؛ تاریخ در زندگی‌نامه","Cardinal and ordinal numbers; dates in biographies","الأعداد الأصلية والترتيبية والتواريخ في السيرة",
    "The chapter distinguishes cardinal numbers from ordinal numbers. It explains that ordinal forms use suffixes such as ـمین or ـم, and that dates in biographies must be written fully and events arranged chronologically.",
    "يميّز الفصل بين الأعداد الأصلية والترتيبية. ويشرح أن العدد الترتيبي يُصاغ بلاحقتي «مین» أو «م»، وأن تواريخ السيرة تُكتب كاملة وتُرتّب الأحداث زمنياً.",
    [S("عدد اصلی","Cardinal number","العدد الأصلي","Counts quantity. The textbook notes that the counted noun after a cardinal number is normally singular in the basic pattern.","يدلّ على الكمية. ويشير الكتاب إلى أن الاسم المعدود يأتي مفرداً عادةً في النمط الأساسي.","در کتابخانه هشت کتاب وجود دارد.","There are eight books in the library.","يوجد في المكتبة ثمانية كتب."),
     S("عدد ترتیبی با ـمین","Ordinal with ـمین","الترتيبي باللاحقة ـمین","Use to state order or position: اولین، دومین، سومین. Observe the noun order in the textbook examples.","يُستعمل لبيان الترتيب: الأول، الثاني، الثالث. انتبه إلى ترتيب الاسم في أمثلة الكتاب.","هتل چهار ستاره در طبقهٔ دومین نیست؛ در طبقهٔ دوم است.","The four-star hotel is on the second floor.","يقع الفندق ذو الأربع نجوم في الطابق الثاني."),
     S("عدد ترتیبی با ـم","Ordinal with ـم","الترتيبي باللاحقة ـم","The lesson contrasts forms such as دوم with forms such as دومین; keep the noun order shown in the model.","يقارن الدرس بين صيغ مثل «دوم» وصيغ مثل «دومین»، مع مراعاة ترتيب الاسم كما في المثال.","امروز درس دوم را خواندیم.","Today we studied the second lesson.","درسنا اليوم الدرس الثاني."),
     S("نوشتن تاریخ زندگی‌نامه","Writing dates in a biography","كتابة التواريخ في السيرة","Write the full year, not a shortened fragment, and arrange the person's life events in chronological order.","اكتب السنة كاملة لا بصورة مختصرة، ورتّب أحداث حياة الشخص ترتيباً زمنياً.","او در سال ۱۳۶۲ به دنیا آمد.","He was born in 1362 SH.","وُلد سنة 1362 بالتقويم الهجري الشمسي.")]),
   10:L("N2-10 · pp5–8","ساختار نامهٔ رسمی و نشانه‌گذاری","Formal-letter structure and punctuation","بنية الرسالة الرسمية وعلامات الترقيم",
    "A formal letter has an opening, body and closing, with a respectful phrase before the opening and thanks after the closing. It uses formal wording, concise requests and careful proofreading.",
    "تتكوّن الرسالة الرسمية من مقدمة ومتن وخاتمة، مع عبارة احترام قبل المقدمة وشكر بعد الخاتمة. وتستعمل ألفاظاً رسمية وطلبات موجزة ومراجعة لغوية دقيقة.",
    [S("ادب و احترام + مقدمه + متن + پایان + سپاس","Respect + opening + body + closing + thanks","الاحترام + المقدمة + المتن + الخاتمة + الشكر","Begin with a respectful address, state the purpose briefly, make the request clearly, close politely and thank the recipient.","ابدأ بخطاب احترام، واذكر الغرض بإيجاز، وقدّم الطلب بوضوح، واختم بأدب واشكر المتلقي.","به استحضار می‌رساند اینجانب دانشجوی ترم دوم هستم.","I wish to inform you that I am a second-term student.","أودّ إحاطتكم علماً بأنني طالب في الفصل الثاني."),
     S("واژه‌های رسمی","Formal expressions","التعابير الرسمية","The source gives forms such as به استحضار می‌رساند، اینجانب، خواهشمند است and درخواست می‌گردد.","يذكر المصدر تعابير مثل: أحيطكم علماً، أنا الموقّع أدناه، نرجو التكرم، ويُرجى تقديم الطلب.","خواهشمند است با درخواست اینجانب موافقت گردد.","I respectfully request that my application be approved.","يرجى التكرّم بالموافقة على طلبي."),
     S("نشانه‌گذاری","Punctuation","علامات الترقيم","Use punctuation to clarify sentence boundaries, lists, quotations and explanations. The source lesson asks learners to correct punctuation in formal writing.","استعمل علامات الترقيم لتوضيح حدود الجمل والقوائم والاقتباسات والتفسير. ويطلب الدرس تصحيح الترقيم في الكتابة الرسمية.","موضوع نامه: درخواست مرخصی.","Subject of the letter: leave request.","موضوع الرسالة: طلب إجازة."),S("نقطه و ویرگول","Full stop and comma","النقطة والفاصلة","Use a full stop at the end of a complete statement. Use a comma for a short pause, separating items in a list, dividing parts of an address, or setting off an explanatory phrase. The OCR also warns that a comma can prevent a misleading ezafe reading.","ضع النقطة في نهاية الجملة الخبرية التامة. واستعمل الفاصلة للوقفة القصيرة، وفصل عناصر القائمة، وتقسيم أجزاء العنوان، وإحاطة العبارة التوضيحية. وينبّه OCR إلى أن الفاصلة قد تمنع قراءة إضافة غير مقصودة.","فردوسی، مولوی، سعدی و حافظ از بزرگ‌ترین سخنوران ایران هستند.","Ferdowsi, Rumi, Saadi and Hafez are among Iran's greatest poets.","الفردوسي والرومي والسعدي والحافظ من أعظم شعراء إيران."),S("نقطه‌ویرگول، دونقطه، گیومه و پرانتز","Semicolon, colon, quotation marks and parentheses","الفاصلة المنقوطة والنقطتان والاقتباس والقوسان","Use a semicolon between closely related complete clauses; a colon before an explanation or quotation; quotation marks for direct speech or titles; and parentheses for clarifying information or an abbreviation.","استعمل الفاصلة المنقوطة بين جملتين تامتين مترابطتين؛ والنقطتين قبل التفسير أو الاقتباس؛ وعلامتي الاقتباس للكلام المباشر أو العناوين؛ والقوسين للمعلومة التوضيحية أو الاختصار.","معلم گفت: «علم بهتر از ثروت است» (این جمله را به یاد داشته باشید).","The teacher said: “Knowledge is better than wealth” (remember this sentence).","قال المعلم: «العلم أفضل من المال» (تذكّر هذه الجملة).")])
  },
  3:{
   1:L("N3-01 · pp4–6","بند، جملهٔ موضوع و نشانه‌گذاری","Paragraphs, topic sentences and punctuation","الفقرات والجملة الموضوعية وعلامات الترقيم",
    "The lesson teaches a paragraph as a connected group of sentences about one idea. It distinguishes the topic sentence, supporting sentences and closing sentence, and explains indentation and punctuation marks.",
    "يعلّم الدرس أن الفقرة مجموعة جمل مترابطة تدور حول فكرة واحدة. ويميّز الجملة الموضوعية والجمل الداعمة والجملة الختامية، ويشرح الإزاحة وعلامات الترقيم.",
    [S("جملهٔ موضوع، پشتیبان و پایانی","Topic, supporting and concluding sentences","الجملة الموضوعية والداعمة والختامية","The topic sentence states the main idea; supporting sentences explain or exemplify it; the closing sentence signals the end and leaves an important thought.","تذكر الجملة الموضوعية الفكرة الأساسية، وتشرحها الجمل الداعمة أو تمثّل لها، وتعلن الجملة الختامية نهاية الفقرة وتترك فكرة مهمة.","برای یادگیری زبان فارسی تمرین و تکرار لازم است؛ به عبارت دیگر باید بسیار تمرین کنید.","Practice and repetition are necessary to learn Persian; in other words, you must practise a lot.","التدريب والتكرار ضروريان لتعلّم الفارسية؛ وبعبارة أخرى يجب أن تتدرّب كثيراً."),
     S("تورفتگی بند","Paragraph indentation","إزاحة الفقرة","Indent the first line of a new paragraph so the reader can see where a new paragraph begins.","أزح السطر الأول من الفقرة الجديدة ليعرف القارئ بداية فقرة جديدة.","جملهٔ نخستین هر بند کمی تورفتگی دارد.","The first sentence of each paragraph is slightly indented.","يكون السطر الأول من كل فقرة مزاحاً قليلاً."),
     S("نقطه‌ویرگول ؛","Semicolon","الفاصلة المنقوطة","The source uses it between closely related sentences and before explanatory expressions such as به عبارت دیگر or زیرا.","يستعملها المصدر بين جملتين مترابطتين وقبل تعابير تفسيرية مثل «بعبارة أخرى» أو «لأنّ».","او تمرین کرد؛ به عبارت دیگر، برای امتحان آماده شد.","He practised; in other words, he prepared for the exam.","تدرّب؛ وبعبارة أخرى استعدّ للامتحان."),
     S("دونقطه، گیومه و پرانتز","Colon, quotation marks and parentheses","النقطتان وعلامتا الاقتباس والقوسان","Use a colon to introduce a quotation or list; quotation marks for direct speech or a title; parentheses for explanation, an alternative or a prayer phrase.","استعمل النقطتين لتقديم اقتباس أو قائمة، وعلامتي الاقتباس للكلام المباشر أو العنوان، والقوسين للتوضيح أو البديل أو العبارة الدعائية.","معلم گفت: «علم بهتر از ثروت است».","The teacher said: “Knowledge is better than wealth.”","قال المعلم: «العلم أفضل من المال».")]),
   2:L("N3-02 · pp5–6","چهار نوع رابطهٔ زمانی","Four types of temporal relations","أنواع العلاقات الزمنية الأربعة",
    "The textbook distinguishes four temporal relations. Do not treat them as interchangeable: each type tells the reader a different thing about the timing of events. The final list of completion markers is partly unreadable in the OCR, so the examples below distinguish source examples from supplementary equivalents.",
    "يميّز الكتاب أربع علاقات زمنية. لا تستعملها بوصفها مترادفات؛ فكل نوع يبيّن علاقة مختلفة بين أزمنة الأحداث. وقائمة أدوات الانتهاء الأخيرة غير واضحة جزئياً في OCR، لذلك نميّز مثال المصدر من البدائل التعليمية الإضافية.",
    [S("۱. رابطهٔ زمانی ترتیبی","1. Sequential relation","١. التتابع الزمني","Shows that events happen one after another in chronological order. Source markers: سپس، بعد از آن، آن‌گاه، پس از آن.","تدلّ على وقوع الأحداث واحداً بعد الآخر وفق الترتيب الزمني. أدوات المصدر: ثمّ، بعد ذلك، عندئذ، من بعد ذلك.","او در فرانسه تحصیل کرد؛ سپس به ایران بازگشت.","He studied in France; then he returned to Iran.","درس في فرنسا، ثم عاد إلى إيران."),
     S("۲. رابطهٔ هم‌زمانی","2. Simultaneous relation","٢. التزامن","Shows two events taking place at the same time. Source markers: همان هنگام، آن وقت، در همان حال، هم‌زمان با آن، در همان موقع.","تدلّ على وقوع حدثين في الوقت نفسه. أدوات المصدر: في الوقت نفسه، حينئذ، في تلك الأثناء، بالتزامن مع ذلك.","احمد هم‌زمان با تحصیل در دانشگاه، به تدریس مشغول بود.","Ahmad was teaching while studying at university.","كان أحمد يدرّس بالتزامن مع دراسته في الجامعة."),
     S("۳. رابطهٔ زمانی ارجاعی","3. Temporal reference","٣. الإحالة الزمنية","Places an event before another event or refers back/forward in time. Source markers: پیش از آن، قبل از آن، زودتر از آن.","تضع حدثاً قبل حدث آخر أو تحيل إلى زمن سابق أو لاحق. أدوات المصدر: قبل ذلك، من قبل، في وقت أسبق.","سعید پیش از آنکه در دانشگاه ثبت‌نام کند، به ایران سفر کرد.","Saeed travelled to Iran before registering at university.","سافر سعيد إلى إيران قبل أن يسجّل في الجامعة."),
     S("۴. رابطهٔ زمانی انجامی","4. Completion relation","٤. انتهاء الحدث","Signals that an event or sequence has reached its end. The OCR's marker list is damaged; بالاخره appears in the source example. Supplementary equivalents for practice: سرانجام، در پایان.","تشير إلى بلوغ الحدث أو سلسلة الأحداث نهايتها. قائمة الأدوات في OCR تالفة؛ وترد «بالاخره» في مثال المصدر. ومن البدائل التعليمية: أخيراً، في النهاية.","احمد بالاخره توانست در رشتهٔ پزشکی قبول شود.","Ahmad finally succeeded in being admitted to medical school.","تمكّن أحمد أخيراً من القبول في كلية الطب.")]),
   3:L("N3-03 · pp4–6","زاویهٔ دید درونی و بیرونی؛ زمان فعل","Inner and outer point of view; verb tense","وجهة النظر الداخلية والخارجية وزمن الفعل",
    "Inner point of view narrates through a character using من/ما. Outer point of view uses a third-person narrator (او). The lesson also reviews four past-tense forms and insists that the tense must match the time being described.",
    "تروي وجهة النظر الداخلية من خلال شخصية تستعمل «من/ما»، أما الخارجية فتستعمل راوياً بضمير الغائب «او». ويراجع الدرس أربعة أزمنة ماضية ويؤكد ضرورة مطابقة الزمن للوقت الموصوف.",
    [S("زاویهٔ دید درونی","Inner point of view","وجهة النظر الداخلية","The narrator is a character in the story and speaks as من or ما.","الراوي شخصية داخل القصة ويتكلم بضمير «أنا» أو «نحن».","من خانهٔ مادربزرگم را به یاد دارم.","I remember my grandmother's house.","أتذكّر بيت جدّتي."),
     S("زاویهٔ دید بیرونی","Outer point of view","وجهة النظر الخارجية","The narrator is outside the events and describes them in the third person.","الراوي خارج الأحداث ويصفها بضمير الغائب.","او خانهٔ مادربزرگش را به یاد داشت.","He remembered his grandmother's house.","كان يتذكّر بيت جدّته."),
     S("گذشتهٔ ساده","Simple past","الماضي البسيط","A completed event at a specific past time: بن ماضی + شناسه.","حدث اكتمل في زمن ماضٍ محدد: جذر الماضي مع علامة الشخص.","او دو سال پیش از دنیا رفت.","He died two years ago.","توفّي قبل عامين."),
     S("گذشتهٔ استمراری","Past continuous","الماضي المستمر","A continuing or habitual action in the past: می + past stem + ending.","عمل مستمر أو معتاد في الماضي: «می» + جذر الماضي + النهاية.","صبح‌ها به خانه‌اش می‌رفتم.","I used to go to his house in the mornings.","كنت أذهب إلى بيته صباحاً."),
     S("گذشتهٔ نقلی و بعید","Present perfect and pluperfect","الماضي النقلي والماضي الأسبق","Present perfect uses the past participle plus personal ending; pluperfect uses the past participle plus بود and an ending. The latter marks an event earlier than another past event.","يتكوّن الماضي النقلي من اسم المفعول مع علامة الشخص؛ ويتكوّن الماضي الأسبق من اسم المفعول مع «بود» وعلامة الشخص، ويدلّ على حدث سبق حدثاً ماضياً آخر.","من نوشته‌ام؛ پیش از آمدن او نوشته بودم.","I have written; I had written before he arrived.","لقد كتبت؛ وكنت قد كتبت قبل وصوله.")]),
   4:L("N3-04 · pp5–6","فعل مضارع ساده، اخباری و التزامی","Simple present, indicative and subjunctive","المضارع البسيط والإخباري والالتزامي",
    "The chapter presents three present-tense forms and explains the uses of the indicative and subjunctive. The subjunctive often expresses doubt, wish, condition or necessity.",
    "يعرض الفصل ثلاث صيغ للمضارع ويشرح استعمالات الإخباري والالتزامي. ويعبّر الالتزامي غالباً عن الشك أو التمني أو الشرط أو الوجوب.",
    [S("مضارع ساده","Simple present","المضارع البسيط","Form: present stem + personal ending. The OCR example is دارد from داشتن.","الصيغة: جذر المضارع مع علامة الشخص. مثال OCR: «دارد» من «داشتن».","او یک کتاب دارد.","He has a book.","لديه كتاب."),
     S("مضارع اخباری: می + بن مضارع + شناسه","Indicative present","المضارع الإخباري","Use for current actions, ongoing truths, habits and sometimes scheduled future actions.","يُستعمل للأفعال الحالية والحقائق المستمرة والعادات، وأحياناً للمستقبل المرتّب.","من هر روز به کتابخانه می‌روم.","I go to the library every day.","أذهب إلى المكتبة كل يوم."),
     S("مضارع التزامی","Subjunctive present","المضارع الالتزامي","Use for doubt (شاید)، wishes (کاش)، conditions (اگر) and necessity (باید). The source notes that ب may sometimes be omitted.","يُستعمل للشك «شاید»، والتمني «کاش»، والشرط «اگر»، والوجوب «باید». ويذكر المصدر أن حرف «ب» قد يُحذف أحياناً.","شاید سعید بیاید؛ اگر تو بیایی، من هم می‌آیم.","Perhaps Saeed will come; if you come, I will come too.","ربما يأتي سعيد؛ إذا أتيتَ فسآتي أنا أيضاً.")]),
   5:L("N3-05 · pp4–6","مراحل نوشتن متن توصیفی و مطابقت نهاد و فعل","Descriptive writing process and subject–verb agreement","مراحل كتابة النص الوصفي ومطابقة الفاعل والفعل",
    "The lesson teaches a seven-step descriptive-writing process: choose a topic, brainstorm, collect features, organise general-to-specific details, draft, revise and prepare a final copy. It then reviews agreement between subject and verb.",
    "يعلّم الدرس سبع مراحل للكتابة الوصفية: اختيار الموضوع، والعصف الذهني، وجمع الصفات، وتنظيم التفاصيل من العام إلى الخاص، وكتابة المسودة، والمراجعة، وإعداد النسخة النهائية. ثم يراجع مطابقة الفاعل والفعل.",
    [S("از کلی به جزئی","General to specific","من العام إلى الخاص","In the body, first describe general features, then specific details. A closing sentence should leave one notable point.","في المتن اذكر الصفات العامة أولاً، ثم التفاصيل الخاصة. وينبغي أن تترك الجملة الختامية نقطة جديرة بالانتباه.","ابتدا طبیعت منطقه را معرفی کنید؛ سپس رنگ و شکل چشمه را توضیح دهید.","First introduce the area's nature; then describe the spring's colour and shape.","قدّم طبيعة المنطقة أولاً، ثم صف لون النبع وشكله."),
     S("بازبینی و پاک‌نویس","Revision and final copy","المراجعة والنسخة النهائية","After drafting, revise content, spelling and punctuation before producing the clean final text.","بعد كتابة المسودة راجع المحتوى والإملاء والترقيم قبل إعداد النسخة النهائية.","متن را از نظر املا و نشانه‌گذاری اصلاح کنید.","Correct the text for spelling and punctuation.","صحّح النص من حيث الإملاء والترقيم."),
     S("مطابقت نهاد و فعل","Subject–verb agreement","مطابقة الفاعل والفعل","A singular subject normally takes a singular verb. Animate plural subjects usually take plural verbs; inanimate plural subjects may take singular or plural according to the source rule. A respectful singular subject may take a plural verb.","يأخذ الفاعل المفرد فعلاً مفرداً عادةً. ويأخذ جمع العاقل غالباً فعلاً جمعاً، أما جمع غير العاقل فقد يأتي معه المفرد أو الجمع بحسب القاعدة. وقد يأتي الفعل الجمع مع المفرد للاحترام.","گنجشک‌ها از روی درخت پریدند؛ ایشان فرمودند.","The sparrows flew from the tree; he/she said (respectfully).","طارَت العصافير عن الشجرة؛ وقال (بصيغة الاحترام).")]),
   6:L("N3-06 · pp5–6","نقد منصفانه و جمله‌های شرطی ممکن","Fair criticism and possible conditional sentences","النقد المنصف والجمل الشرطية الممكنة",
    "The chapter teaches balanced criticism: mention strengths and weaknesses, support opinions with reasons, and use cautious phrases when uncertain. It then introduces possible conditional sentences.",
    "يعلّم الفصل النقد المتوازن: ذكر نقاط القوة والضعف، ودعم الرأي بالأسباب، واستعمال عبارات احترازية عند عدم اليقين. ثم يقدّم الجمل الشرطية الممكنة.",
    [S("عبارت‌های احتیاط در نقد","Cautious expressions in criticism","عبارات التحفّظ في النقد","Use به نظر می‌رسد، ممکن است and شاید when presenting an interpretation that is not certain.","استعمل «يبدو أن»، و«من الممكن»، و«ربما» عند عرض تفسير غير يقيني.","به نظر می‌رسد نویسنده می‌خواهد به این نکته اشاره کند.","It seems that the writer wants to point out this idea.","يبدو أن الكاتب يريد الإشارة إلى هذه الفكرة."),
     S("شرطی ممکن","Possible conditional","الشرط الممكن","The OCR gives patterns including اگر + past simple + indicative present, and condition forms followed by a command. The result depends on the condition being fulfilled.","يعرض OCR تراكيب منها «اگر + الماضي البسيط + المضارع الإخباري»، وصيغ شرط يتبعها أمر. ويتوقف تحقق النتيجة على تحقق الشرط.","اگر باران ببارد، زمین سرسبز می‌شود.","If it rains, the ground becomes green.","إذا هطل المطر اخضرّت الأرض.")]),
   7:L("N3-07 · pp5–6","برنامه‌ریزی، بندنویسی و شرطی غیرممکن","Planning, paragraph writing and impossible conditionals","التخطيط وكتابة الفقرة والشرط غير الممكن",
    "The chapter teaches planning priorities and time, paragraph unity and the distinction between possible and impossible conditions. The OCR table for impossible-condition forms is damaged; the lesson's examples are therefore presented as practice prompts, not as a fully reconstructed paradigm.",
    "يعلّم الفصل ترتيب الأولويات والوقت، ووحدة الفقرة، والتمييز بين الشرط الممكن وغير الممكن. جدول صيغ الشرط غير الممكن تالف في OCR؛ لذلك نعرض أمثلة الدرس للتدريب ولا ندّعي إعادة بناء جدول التصريف كاملاً.",
    [S("وحدت بند","Paragraph unity","وحدة الفقرة","Every sentence in a paragraph should relate to one topic; remove sentences that do not support the topic sentence.","ينبغي أن ترتبط كل جملة في الفقرة بموضوع واحد؛ واحذف الجمل التي لا تدعم الجملة الموضوعية.","جمله‌های یک بند باید دربارهٔ یک موضوع باشند.","The sentences in one paragraph should be about one topic.","يجب أن تدور جمل الفقرة الواحدة حول موضوع واحد."),
     S("اولویت‌بندی برنامه","Prioritising a plan","ترتيب أولويات الخطة","List tasks, place important tasks first, allocate time and leave room for revision and practice.","اكتب المهام، وقدّم المهم منها، وحدّد الوقت واترك مجالاً للمراجعة والتدريب.","ابتدا کارهای مهم را انجام می‌دهم؛ سپس وقت مرور می‌گذارم.","I do the important tasks first; then I set aside time to review.","أنجز المهام المهمة أولاً، ثم أخصّص وقتاً للمراجعة."),
     S("شرطی غیرممکن","Impossible / counterfactual conditional","الشرط غير الممكن أو المخالف للواقع","The chapter contrasts these with possible conditions. Use the textbook's sentence-completion exercise and preserve the past-time viewpoint; the damaged OCR table should be checked against the printed book before memorising exact formulas.","يقارن الفصل هذه الصيغ بالشروط الممكنة. أكمل تمرين الكتاب مع الحفاظ على منظور الزمن الماضي؛ وينبغي مراجعة الجدول التالف في النسخة المطبوعة قبل حفظ الصيغ الدقيقة.","اگر برای امتحان برنامه‌ریزی کرده بودی، ...","If you had planned for the exam, ...","لو كنت قد خططت للامتحان، ...")]),
   8:L("N3-08 · pp5–6","خلاصه‌نویسی به مفهوم و به حذف","Summary by meaning and by deletion","التلخيص بإعادة الصياغة وبالحذف",
    "The chapter distinguishes two methods. A meaning-based summary restates each paragraph's main point in concise language; a deletion-based summary removes details that do not affect the central meaning.",
    "يميّز الفصل بين طريقتين: تلخيص بالمعنى يعيد صياغة الفكرة الأساسية لكل فقرة بإيجاز، وتلخيص بالحذف يزيل التفاصيل التي لا تؤثر في المعنى المركزي.",
    [S("خلاصه به مفهوم","Meaning-based summary","التلخيص بالمعنى","Read for understanding, note the main topic, summarise each paragraph separately and identify the author's overall purpose.","اقرأ للفهم، وسجّل الموضوع الرئيس، ولخّص كل فقرة على حدة، ثم حدّد هدف الكاتب العام.","نویسنده دربارهٔ اهمیت آموزش و نقش معلم توضیح می‌دهد.","The writer explains the importance of education and the teacher's role.","يشرح الكاتب أهمية التعليم ودور المعلم."),
     S("خلاصه به حذف","Deletion-based summary","التلخيص بالحذف","Remove repeated names, decorative descriptions, examples and sentences that do not change the main meaning. Keep the essential claim and evidence.","احذف تكرار الأسماء والأوصاف الزخرفية والأمثلة والجمل التي لا تغيّر المعنى الأساسي. وأبقِ الفكرة والدليل الضروريين.","جزئیات تکراری را حذف کنید و پیام اصلی را نگه دارید.","Remove repeated details and keep the main message.","احذف التفاصيل المكررة واحتفظ بالرسالة الأساسية.")]),
   9:L("N3-09 · pp5–6","فعل امر مفرد و جمع","Singular and plural imperative","فعل الأمر للمفرد والجمع",
    "The chapter states that the imperative is used for second-person singular and second-person plural. The plural imperative has the same visible form as the second-person plural subjunctive, so context determines the function.",
    "يذكر الفصل أن فعل الأمر يُستعمل للمخاطب المفرد والمخاطب الجمع. وتتطابق صورة الأمر للجمع ظاهرياً مع المضارع الالتزامي للمخاطب الجمع، لذلك يحدّد السياق الوظيفة.",
    [S("امر مفرد","Singular imperative","الأمر للمفرد","Use for one listener: برو، بنویس، بیا.","يُستعمل لمخاطب واحد: اذهب، اكتب، تعال.","ابتدا در سایت ثبت‌نام کن.","First register on the website.","سجّل أولاً في الموقع."),
     S("امر جمع","Plural / respectful imperative","الأمر للجمع أو الاحترام","Use بروید، بنویسید, etc. for several listeners or one listener respectfully.","استعمل «بروید» و«بنویسید» للجماعة أو للاحترام.","برای شرکت در کلاس انتخاب کنید.","Choose a time to attend the class.","اختر وقتاً للمشاركة في الدرس."),
     S("امر جمع و مضارع التزامی","Plural imperative vs plural subjunctive","الأمر الجمع والمضارع الالتزامي","The visible form may be identical; distinguish it by the sentence's purpose and surrounding words.","قد تتطابق الصورة الظاهرة؛ فميّز بينهما من غرض الجملة والكلمات المحيطة.","بروید! / شاید بروید.","Go! / Perhaps you will go.","اذهبوا! / ربما تذهبون.")]),
   10:L("N3-10 · pp5–9","پرسش تحقیق، ارجاع، چکیده و کلیدواژه","Research questions, references, abstract and keywords","أسئلة البحث والإحالات والملخص والكلمات المفتاحية",
    "The chapter defines three research-question types—descriptive, relational and comparative—and teaches source notes, bibliographic references, headings, abstracts and 5–8 keywords.",
    "يعرّف الفصل ثلاثة أنواع من أسئلة البحث: الوصفية والعلاقية والمقارنة، ويعلّم تدوين المصادر والمراجع والعناوين والملخص وكتابة ٥ إلى ٨ كلمات مفتاحية.",
    [S("پرسش توصیفی","Descriptive question","السؤال الوصفي","Asks what something is or how it happens: چیست؟ چگونه است؟ چقدر است؟","يسأل عن ماهية الشيء أو كيفية حدوثه: ما هو؟ كيف؟ كم؟","مراسم جشن‌های هندی‌ها چگونه برگزار می‌شود؟","How are Indian festivals celebrated?","كيف تُقام الاحتفالات الهندية؟"),
     S("پرسش رابطه‌ای","Relational question","السؤال العلاقي","Asks how two or more things are connected or how one affects another.","يسأل عن العلاقة بين أمرين أو أكثر أو تأثير أحدهما في الآخر.","دعا چه تأثیری در زندگی انسان دارد؟","What effect does prayer have on human life?","ما أثر الدعاء في حياة الإنسان؟"),
     S("پرسش مقایسه‌ای","Comparative question","السؤال المقارن","Examines similarities or differences between two or more things. Avoid a yes/no question beginning with آیا when the research needs an explanatory answer.","يدرس أوجه التشابه أو الاختلاف بين أمرين أو أكثر. وتجنّب سؤال نعم/لا الذي يبدأ بـ«آیا» إذا كان البحث يحتاج إلى إجابة تفسيرية.","چه تفاوتی بین جشن‌های ملی ایران و پاکستان وجود دارد؟","What is the difference between the national festivals of Iran and Pakistan?","ما الفرق بين الأعياد الوطنية في إيران وباكستان؟"),
     S("ارجاع به منبع","Referencing a source","الإحالة إلى المصدر","Record author surname and name, publication year, title, volume, city, publisher and page. Alphabetise references; list the Qur'an, Nahj al-Balagha and Sahifa Sajjadiya first when used, as the textbook directs.","سجّل لقب المؤلف واسمه وسنة النشر والعنوان والمجلد والمدينة والناشر والصفحة. رتّب المراجع أبجدياً، وقدّم القرآن ونهج البلاغة والصحيفة السجادية أولاً إذا استُعملت، وفق توجيه الكتاب.","نام خانوادگی، نام. (سال). عنوان کتاب، شهر: ناشر، ص. شماره.","Surname, name. (year). Book title, city: publisher, p. number.","اسم العائلة، الاسم. (السنة). عنوان الكتاب، المدينة: الناشر، ص. الرقم."),
     S("چکیده و ۵ تا ۸ کلیدواژه","Abstract and 5–8 keywords","الملخص و٥ إلى ٨ كلمات مفتاحية","Write the abstract after completing the research, but place it on the first page. Include topic, method, main points and findings; then list 5–8 essential terms.","اكتب الملخص بعد إتمام البحث، لكن ضعه في الصفحة الأولى. واذكر الموضوع والمنهج وأهم النقاط والنتائج، ثم أدرج ٥ إلى ٨ مصطلحات أساسية.","چکیده شامل موضوع، روش تحقیق، مطالب مهم و یافته‌هاست.","The abstract includes the topic, method, key content and findings.","يتضمن الملخص الموضوع والمنهج وأهم المضامين والنتائج.")])
  }
 };
 window.NEWESTAN_LANGUAGE_LESSONS=D;
 window.renderNewestanLanguageLesson=(term,no)=>{
  const rec=(D[Number(term)]||{})[Number(no)];if(!rec)return "";
  const e=s=>typeof esc==="function"?esc(s||""):String(s||"");
  return '<section class="newestan-language-lesson"><div class="newestan-language-heading"><span class="newestan-language-kicker">BIYĀMOZĪM · بیاموزیم</span><h3>'+e(rec.titleFa)+'</h3><p>'+e(rec.titleEn)+' · '+e(rec.titleAr)+'</p><small>OCR source: '+e(rec.source)+'</small></div><p class="newestan-language-overview">'+e(rec.overviewEn)+'</p><p class="newestan-language-overview fa-block" dir="rtl">'+e(rec.overviewAr)+'</p><div class="newestan-language-rules">'+rec.sections.map(rule=>'<article class="newestan-language-rule"><div class="newestan-language-rule-title"><b>'+e(rule.fa)+'</b><span>'+e(rule.en)+' · '+e(rule.ar)+'</span></div><p>'+e(rule.whenEn)+'</p><p class="fa-block" dir="rtl">'+e(rule.whenAr)+'</p><div class="newestan-language-example"><div class="fa-block" dir="rtl">'+e(rule.exampleFa)+'</div><div>'+e(rule.exampleEn)+'</div><div class="fa-block" dir="rtl">'+e(rule.exampleAr)+'</div></div></article>').join("")+'</div></section>';
 };
})();